import './about.css';
import aboutImg from "../../assets/Nikki.jpg";
import CV from "../../assets/NikithaResume.pdf";
import { Info } from './info';
import { SectionHeading } from '../section-heading';
export function About(){
    return(
            <section className="about section" id="about">
                <div className="container">
                <SectionHeading eyebrow="A little about me" title="About me" subtitle="The person behind the pixels" />
                <div className="about__container grid">
                    <div className="about__visual">
                        <img src={aboutImg} alt="Nikitha Vedant Madabhushi" className="about__img" />
                    </div>
                    <div className="about__data">
                        <Info />
                        <p className="about__description">I’m a frontend developer with two years of experience creating responsive web experiences with React, HTML, CSS, and JavaScript. I enjoy turning complex ideas into interfaces that feel clear, useful, and welcoming.</p>
                        <a href={CV} className="button" download>
                            Download résumé <i className="uil uil-import" aria-hidden="true"></i>
                        </a>
                    </div>
                </div>
                </div>
            </section>
    )
}
